create or replace function public.publish_intelligence_location_event(p_location_id uuid,p_event_type text,p_title text,p_body text,p_payload jsonb default '{}'::jsonb,p_radius_m integer default 10000,p_dedupe_key text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_notification_id uuid; v_dedupe text; begin v_dedupe:=coalesce(p_dedupe_key,p_event_type||':'||p_location_id::text||':'||date_trunc('hour',now())::text); insert into public.notification_events(event_type,actor_user_id,location_id,audience_scope,payload,dedupe_key,expires_at) values(p_event_type,auth.uid(),p_location_id,'nearby',jsonb_build_object('title',p_title,'body',p_body)||coalesce(p_payload,'{}'::jsonb),v_dedupe,now()+interval '24 hours') on conflict(dedupe_key) where dedupe_key is not null do update set payload=excluded.payload,created_at=now(),expires_at=excluded.expires_at returning id into v_notification_id; insert into public.notification_deliveries(notification_id,recipient_user_id,channel) select v_notification_id,r.user_id,'in_app' from public.resolve_nearby_notification_recipients(p_location_id,p_radius_m) r on conflict(notification_id,recipient_user_id,channel) do nothing; insert into public.notification_deliveries(notification_id,recipient_user_id,channel) select v_notification_id,r.user_id,'push' from public.resolve_nearby_notification_recipients(p_location_id,p_radius_m) r on conflict(notification_id,recipient_user_id,channel) do nothing; perform public.materialize_notification_event(v_notification_id); perform public.queue_push_deliveries_for_notification(v_notification_id); return v_notification_id; end; $$;
